55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const CURSE_SURCHARGE = 0.5;
60	
61	const HIGH_ENCHANTMENT_LEVEL = 5;
62	
63	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
64	
65	const BASE_PREMIUMS: Record<string, number> = {
66	  sword: 100,
67	  amulet: 60,
68	  staff: 80,
69	  potion: 40,
70	  rune: 25,
71	  moonstone: 25,
72	};
73	
74	const BLOCK_SIZE = 3;
75	
76	const BLOCK_BASE_PREMIUM = 60;
77	
78	const countsByType = (items: Item[]): Map<string, number> => {
79	  const counts = new Map<string, number>();
80	
81	  for (const item of items) {
82	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
83	  }
84	
85	  return counts;
86	};
87	
88	const groupBasePremium = (type: string, count: number): number =>
89	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
90	
91	const policyBasePremium = (items: Item[]): number =>
92	  [...countsByType(items)].reduce(
93	    (total, [type, count]) => total + groupBasePremium(type, count),
94	    0,
95	  );
96	
97	// Modifiers below all express a rate applied to some base. Keep every one of
98	// them in the form `base + base * RATE`. The algebraically equivalent
99	// `base * (1 + RATE)` is NOT safe here: 100 * 1.1 === 110.00000000000001 in
100	// IEEE-754, and Math.ceil turns that into 116 instead of 115. Ceil amplifies
101	// upward float error rather than absorbing it.
102	
103	// Item-specific modifiers: each is computed on the affected item's OWN base
104	// premium, then summed across items.
105	const itemSurchargeRate = (item: Item): number =>
106	  (item.cursed ? CURSE_SURCHARGE : 0) +
107	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
108	    ? HIGH_ENCHANTMENT_SURCHARGE
109	    : 0);
110	
111	const itemSurcharges = (items: Item[]): number =>
112	  items.reduce(
113	    (total, item) => total + BASE_PREMIUMS[item.type] * itemSurchargeRate(item),
114	    0,
115	  );
116	
117	// Policy-wide modifiers: each is computed on the policy base premium (the sum
118	// of all item base premiums), independent of which items make it up.
119	const policySurcharges = (policyBase: number): number =>
120	  policyBase * FIRST_INSURANCE_SURCHARGE;
121	
122	const quote = (items: Item[]): QuoteResult => {
123	  const policyBase = policyBasePremium(items);
124	
125	  return {
126	    premium: Math.ceil(
127	      policyBase +
128	        itemSurcharges(items) +
129	        policySurcharges(policyBase) +
130	        PROCESSING_FEE,
131	    ),
132	  };
133	};
134	
135	const runStep = (step: Step): StepResult => {
136	  if (step.op === "quote") return quote(step.items);
137	
138	  throw new Error(`Unsupported step: ${step.op}`);
139	};
140	
141	export const runScenario = (scenario: Scenario): ScenarioResult => ({
142	  results: scenario.steps.map(runStep),
143	});
